def merge_events(events, table):
    for event in events:
        table.upsert(event, key='event_id')

def reprocess(batch_id, raw_path):
    transformed = transform(read(raw_path))
    write(raw_path, transformed)

def rebuild_current(events):
    state = {}
    for event in events:
        if event['op'] in {'insert', 'update'}:
            state[event['id']] = event['row']
    return state
